- findPlotForUpdate(plotCode) -> PlotRow (id, code, status, capacity)
- countActiveTransplants(plotId)
- findTransplantByRequestId(requestId)
- findTransplantByPlantCode(plantCode)
- insertTransplant(...)
- updateTransplantStatus(id, status)
- findReviewByRequestId(requestId)
- insertReview(...)
- findReviewsByTransplantId(id)
- findSealByPlotId(plotId)
